document.addEventListener('input', event => { if (event.target.id === 'record-search') { state.filter = event.target.value; $('#records-table').innerHTML = filteredRecords(); } });
document.addEventListener('change', event => { if (event.target.id === 'status-filter') { state.statusFilter = event.target.value; $('#records-table').innerHTML = filteredRecords(); } });
